import{_ as i,l,o as e,c as n,v as r,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"谓词逻辑与量词","description":"","frontmatter":{"title":"谓词逻辑与量词","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/predicate-logic.md","filePath":"cs/predicate-logic.md","lastUpdated":1789023840000}'),c={name:"cs/predicate-logic.md"};function m(_,a,u,f,E,T){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="谓词逻辑与量词" tabindex="-1">谓词逻辑与量词 <a class="header-anchor" href="#谓词逻辑与量词" aria-label="Permalink to &quot;谓词逻辑与量词&quot;">​</a></h1><div class="epigraph"><p>一阶逻辑把原子换成关系与函数，加上 $\\forall,\\exists$。有效式可半判定，不可判定；有限模型上又回到 SAT 的亲戚。</p><footer>—— 据 Enderton；Church, 1936；Turing, 1936 整理</footer></div><p>上一课<a href="/cs/propositional-logic-cnf">命题与范式</a> 的赋值是有限 \\(2^n\\)。缺口是<strong>一阶</strong>：论域可无限，量词绑定变元。程序规范「对所有输入」落在这里。本课钉语法、结构、满足，以及 Church 不可判定；自然演绎下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言：函数符、谓词符、等号。项、原子、公式。结构 \\(\\mathfrak{M}\\)：论域 \\(|\\mathfrak{M}|\\)，解释符号。赋值把自由变元映到论域。\\(\\mathfrak{M}\\models\\varphi\\) 闭式为真。有效：一切结构为真。命题是一阶的无量词、无函数的碎片。</p><p>有效性 RE 完全（完备性给半判定：能证则有效，且可枚举证明）。不可判定：把 TM 停机编成句子（Church–Turing）。有限模型上，一阶句子的有限可满足仍不可判定（Trakhtenbrot），点名。</p><h3 id="不是「英语的所有-存在」" tabindex="-1">不是「英语的所有 / 存在」 <a class="header-anchor" href="#不是「英语的所有-存在」" aria-label="Permalink to &quot;不是「英语的所有 / 存在」&quot;">​</a></h3><p>量词论域由结构指定，不是宇宙中的一切东西。换结构，同一句子真值可翻。绑定与 λ 课的捕获同一卫生问题。</p><p><span class="marginnote">Enderton 一阶章。Church 1936 判定问题。Gödel 完备性（下一课可靠完备的一阶版）。本课不进二阶逻辑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(\\forall x\\exists y\\ R(x,y)\\) 在自然数后继与在有限图上的不同。Skolem：\\(\\forall x\\exists y\\) 换成函数 \\(f(x)\\)，等可满足。Prenex 点名。不要把 Prolog 当定义。</p>',11)),(e(),s(p,null,{default:t(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E5%91%BD%E9%A2%98%22%5D%20--%3E%20FOL%5B%22%E9%A1%B9%20%2B%20%E9%87%8F%E8%AF%8D%22%5D%0A%20%20FOL%20--%3E%20STR%5B%22%E7%BB%93%E6%9E%84%20%E2%8A%A8%22%5D%0A%20%20FOL%20--%3E%20UND%5B%22%E6%9C%89%E6%95%88%E6%80%A7%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Hoare 逻辑的断言语言需要量词谈数组全体下标。SMT 把一阶碎片（算术、数组）交给判定器——可判定理论是特例，不是本课的完全一阶。本课先承认一般一阶太宽。</p><p>Herbrand：无等式时，可满足性与基项上的命题可满足相关，给 SMT 实例化埋伏。</p><p>自由变元必须在结构里赋值才有真值；闭式才谈 \\(\\mathfrak{M}\\models\\varphi\\)。空论域约定因系统而异，本课默认非空。二阶量词可谈「存在性质」，表达力骤升、证明论不同。Trakhtenbrot：有限可满足不可判定，故「只关心有限模型」帮不掉一般一阶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证完备性，不写公理表。不引入集合论公理化。后课默认：规范写成一阶公式相对某结构；有效性不可判定。下一课证明系统：自然演绎。</p><p>有效性可半判定（枚举证明）但不可判定。程序规范里的「对所有输入」是一阶句子相对某结构，不是英语全称。SMT 后课只占领可判定碎片，不收回本课的否定结果。</p><p>上一课留下的缺口在本课收口；「谓词逻辑与量词」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一阶：结构解释函数与关系；量词在论域上走。</li><li>有效可半判定、不可判定。</li><li>命题是无量词碎片；程序规范需要量词。</li><li>出处：Enderton；Church, 1936。</li></ul>',10))])}const b=i(c,[["render",m]]);export{A as __pageData,b as default};
